const SHADOW = "0 30px 70px rgba(22,11,51,0.12), 0 4px 14px rgba(22,11,51,0.06)";
const SHADOW_D = "0 44px 90px rgba(22,11,51,0.30), 0 6px 18px rgba(22,11,51,0.14)";

// texto: entra desfocado com leve escala, assenta e fica parado; sai desfocando no mesmo lugar
const blurIn = (t: number, at: number, out?: number, d = 0.45): React.CSSProperties => {
  const e = k(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.2);
  return {
    opacity: Math.min(1, e * 1.6) * (1 - o),
    filter: `blur(${((1 - e) * 18 + o * 14).toFixed(1)}px)`,
    transform: `scale(${(0.9 + 0.1 * e).toFixed(4)})`,
  };
};
const grad = (g: string): React.CSSProperties => ({ backgroundImage: g, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent" });

type L = [string, number, boolean?];
const Lines: React.FC<{ t: number; items: L[]; size: number; top: number; color?: string; out?: number; weight?: number }> = ({ t, items, size, top, color = INK, out, weight = 600 }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center" }}>
