        {w}
      </div>
    ))}
  </div>
);

// ───────── tela real do sistema num cartão escuro ─────────
// cada corte mostra um recorte do vídeo: [x, y, largura] em pixels do arquivo; a altura sai da proporção do cartão
type Cut = { src: string; sw: number; sh: number; a: number; b: number; start: number; rate?: number; crop: [number, number, number]; zoom?: [number, number] };
const Screen: React.FC<{ t: number; cuts: Cut[]; w: number; h: number; r?: number }> = ({ t, cuts, w, h, r = 40 }) => {
  const { fr } = useLoc();
  return (
  <div style={{ position: "relative", width: w, height: h, borderRadius: r, overflow: "hidden", background: NIGHT, boxShadow: SHADOW_D }}>
    {cuts.map((c, i) => {
      const s = w / c.crop[2];
      const z = c.zoom ? interpolate(t, [c.a, c.b], c.zoom, cl) : 1 + 0.05 * lin(t, c.a, c.b);
      return (
        <Sequence key={i} from={fr(c.a)} durationInFrames={Math.max(1, fr(c.b) - fr(c.a))} layout="none">
          <div style={{ position: "absolute", inset: 0, transform: `scale(${z.toFixed(4)})` }}>
            <OffthreadVideo muted src={staticFile(`avalom/${c.src}.mp4`)} trimBefore={Math.round(c.start * AVA_FPS)} playbackRate={c.rate ?? 1} style={{ position: "absolute", width: c.sw * s, height: c.sh * s, left: -c.crop[0] * s, top: -c.crop[1] * s, maxWidth: "none" }} />
          </div>
        </Sequence>
      );
    })}
    <div style={{ position: "absolute", inset: 0, borderRadius: r, border: "1.5px solid rgba(255,255,255,0.10)", boxSizing: "border-box" }} />
  </div>
  );
};
// impulso do cartão a cada corte
const punch = (t: number, ats: number[], amt = 0.035) => 1 + amt * ats.reduce((m, a) => Math.max(m, t >= a ? 1 - k(t, a, 0.32) : 0), 0);

