// ───────── cena 1 · o problema: uma IA qualquer (desenhada, sem marca) cospe PDFs; depois, o PDF travado ─────────
const Problema: React.FC<{ t: number }> = ({ t }) => {
  const { tx } = useLoc();
  const PEDIDO = tx.ask;
  const SEND = 0.58, B = 2.85, LOCK = 5.45;
  const cardIn = pop(t, -0.1, 0.5);
  const typed = PEDIDO.slice(0, Math.round(lin(t, 0.0, 0.5) * PEDIDO.length));
  const press = interpolate(t, [SEND - 0.06, SEND, SEND + 0.2], [0, 1, 0], cl);
  const spit = [0.72, 0.9, 1.08, 1.26, 1.44, 1.62, 1.8, 1.98];
  const kick = spit.reduce((m, a) => Math.max(m, t >= a ? 1 - k(t, a, 0.22) : 0), 0);
  const shake = t > LOCK ? Math.sin((t - LOCK) * 46) * 14 * Math.max(0, 1 - (t - LOCK) / 0.4) : 0;
  const gray = lin(t, LOCK, LOCK + 0.3);
  return (
    <AbsoluteFill style={{ background: WHITE, isolation: "isolate" }}>
      <Col x={120} w={760} top={330}>
        {t < B + 0.25 ? <Lines t={t} top={0} size={tx.hookSize} out={B - 0.12} items={tx.hook} /> : null}
        {t >= B - 0.05 ? <Lines t={t} top={tx.gen.length > 3 ? -50 : 0} size={tx.genSize} items={tx.gen} /> : null}
      </Col>
      {/* os PDFs saem de baixo da caixa de pedido */}
      <div style={{ position: "absolute", left: 0, top: 0, width: 1920, height: 1080, transformOrigin: "1380px 640px", transform: `translateX(${shake.toFixed(1)}px) scale(${(1 + 0.12 * lin(t, 2.9, 5.4) - 0.05 * k(t, LOCK, 0.3)).toFixed(4)})`, filter: `grayscale(${gray.toFixed(2)})` }}>
        {spit.map((at, i) => {
          if (t < at) return null;
          const e = k(t, at, 0.5);
          const col = i % 4, wave = Math.floor(i / 4);
          const x = 990 + col * 196 + wave * 22, y = 470 + wave * 190 + Math.sin(t * 3 + i * 1.7) * 14;
          const wv = Math.sin(Math.PI * lin(t, 4.0 + i * 0.07, 4.36 + i * 0.07)) + Math.sin(Math.PI * lin(t, 4.85 + i * 0.07, 5.2 + i * 0.07));
          const r = [-7, 3, 8, -4, 5, -9, 6, -3][i] + Math.sin(t * 2.6 + i) * 5;
          return (
            <div key={i} style={{ position: "absolute", left: 1290 + (x - 1290) * e, top: 330 + (y - 330) * BACK(Math.min(1, e)), zIndex: i, opacity: Math.min(1, e * 4), transform: `rotate(${(r * e + (1 - e) * (i % 2 ? 40 : -40)).toFixed(2)}deg) scale(${(0.35 + 0.65 * e + 0.16 * wv).toFixed(3)})` }}>
              <Doc w={176} tone={i % 2} />
            </div>
          );
        })}
      </div>
      <div style={{ position: "absolute", left: 980, top: 150, width: 800, height: 270, zIndex: 20, borderRadius: 52, background: WHITE, border: `2px solid ${LINE}`, boxSizing: "border-box", boxShadow: SHADOW, opacity: Math.min(1, cardIn * 2), transform: `translateY(${((1 - cardIn) * 160 - kick * 14).toFixed(1)}px) rotate(${((1 - cardIn) * -5).toFixed(2)}deg) scale(${(0.6 + 0.4 * cardIn + 0.22 * (1 - k(t, 0.1, 0.55)) + 0.05 * kick).toFixed(4)})` }}>
        <div style={{ position: "absolute", left: 40, top: 30, display: "flex", alignItems: "center", gap: 16 }}>
          <div style={{ width: 56, height: 56, borderRadius: 18, background: "#B9B4C8", display: "flex", alignItems: "center", justifyContent: "center", transform: `rotate(${(t >= SEND ? (t - SEND) * 200 : 0).toFixed(0)}deg)` }}><IcoSpark s={34} c={WHITE} /></div>
          <span style={{ fontFamily: F, fontWeight: 600, fontSize: 36, color: MUTED, letterSpacing: "-0.02em" }}>{tx.anyAi}</span>
          {t >= SEND && t < 2.2 ? <div style={{ display: "flex", gap: 9, marginLeft: 10 }}>{[0, 1, 2].map((d) => <div key={d} style={{ width: 13, height: 13, borderRadius: 7, background: "#B9B4C8", transform: `translateY(${(-10 * Math.max(0, Math.sin((t - SEND) * 16 - d * 0.9))).toFixed(1)}px)` }} />)}</div> : null}
        </div>
        <div style={{ position: "absolute", left: 36, right: 36, top: 122, height: 112, direction: tx.rtl ? "rtl" : undefined, borderRadius: 56, background: "#F4F3F7", display: "flex", alignItems: "center", padding: "0 16px 0 40px", boxSizing: "border-box" }}>
          <span style={{ fontFamily: F, fontWeight: 600, fontSize: 50, color: INK, letterSpacing: "-0.03em", whiteSpace: "nowrap" }}>{typed}</span>
          <div style={{ width: 4, height: 54, marginLeft: 6, background: INK, opacity: t < SEND && Math.sin(t * 22) > -0.3 ? 1 : 0 }} />
          <div style={{ flex: 1 }} />
          <div style={{ width: 80, height: 80, borderRadius: 40, background: INK, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${(1 - 0.16 * press).toFixed(3)})` }}>
            <svg width={40} height={40} viewBox="0 0 24 24" fill="none" stroke={WHITE} strokeWidth={3} strokeLinecap="round" strokeLinejoin="round"><path d="M12 19V5" /><path d="M5 12l7-7 7 7" /></svg>
          </div>
        </div>
      </div>
      {/* cadeado em "travado" */}
      <div style={{ position: "absolute", left: 1380 - 85 + shake, top: 600, width: 170, height: 170, borderRadius: 85, background: INK, display: "flex", alignItems: "center", justifyContent: "center", zIndex: 30, boxShadow: SHADOW_D, opacity: k(t, LOCK, 0.15), transform: `scale(${(2.2 - 1.2 * k(t, LOCK, 0.28)).toFixed(3)})` }}>
        <IcoLock s={94} c={WHITE} />
      </div>
    </AbsoluteFill>
  );
};

