export const AvalomEbookGptWide: React.FC<{ lang?: AvaWLang }> = ({ lang = "pt" }) => {
  const warp = WARPS[lang];
  const tNew = useCurrentFrame() / AVA_FPS - LEAD;
  const t = warp ? interpolate(tNew, warp.map((p) => p[0]), warp.map((p) => p[1]), cl) : tNew;
  const loc = React.useMemo(() => ({
    tx: TXS[lang],
    fr: warp ? (s: number) => frPt(interpolate(s, warp.map((p) => p[1]), warp.map((p) => p[0]), cl)) : frPt,
  }), [lang, warp]);
  // trocas de cena, cada uma de um jeito: íris · empurrão lateral · folha que sobe · recuo · faixa inclinada ·
  // empurrão para cima · duas metades · círculo do gradiente
  const iris = interpolate(t, [TM - 0.22, TM + 0.26], [0, 1], { ...cl, easing: INOUT });
  const push = interpolate(t, [TE - 0.26, TE + 0.22], [0, 1], { ...cl, easing: INOUT });
  const sheet = interpolate(t, [TV - 0.28, TV + 0.22], [0, 1], { ...cl, easing: OUT });
  const zoomT = interpolate(t, [TF - 0.22, TF + 0.2], [0, 1], { ...cl, easing: INOUT });
  const band = interpolate(t, [TI - 0.3, TI + 0.3], [0, 1], { ...cl, easing: INOUT });
  const up = interpolate(t, [TP - 0.26, TP + 0.22], [0, 1], { ...cl, easing: INOUT });
  const split = interpolate(t, [TN - 0.2, TN + 0.22], [0, 1], { ...cl, easing: INOUT });
  const circ = interpolate(t, [TZ - 0.2, TZ + 0.32], [0, 1], { ...cl, easing: INOUT });
  return (
    <Loc.Provider value={loc}>
    <AbsoluteFill style={{ background: WHITE }}>
      {loc.tx.rtl ? <style>{"* { letter-spacing: 0 !important; }"}</style> : null}
      {t < TM + 0.3 ? <Problema t={t} /> : null}
      {t >= TM - 0.24 && t < TE + 0.25 ? (
        <AbsoluteFill style={{ clipPath: t < TM + 0.3 ? `circle(${(iris * 2300).toFixed(0)}px at 960px 430px)` : undefined, transform: `translateX(${(-push * 1920).toFixed(1)}px)` }}><Marca t={t} /></AbsoluteFill>
      ) : null}
      {t >= TE - 0.42 && t < TV + 0.25 ? (
        <AbsoluteFill style={{ transform: `translateX(${((1 - push) * 1920).toFixed(1)}px) scale(${(1 - 0.05 * sheet).toFixed(4)})` }}><Editor t={t} /></AbsoluteFill>
      ) : null}
      {t >= TV - 0.3 && t < TF + 0.22 ? (
        <AbsoluteFill style={{ transform: `translateY(${((1 - sheet) * 1080).toFixed(1)}px) scale(${(1 + 0.14 * zoomT).toFixed(4)})`, opacity: 1 - zoomT, borderRadius: `${((1 - sheet) * 80).toFixed(0)}px ${((1 - sheet) * 80).toFixed(0)}px 0 0`, overflow: "hidden", boxShadow: "0 -30px 80px rgba(22,11,51,0.18)" }}><Maquina t={t} /></AbsoluteFill>
      ) : null}
      {t >= TF - 0.42 && t < TI + 0.32 ? (
        <AbsoluteFill style={{ opacity: t < TF + 0.22 ? zoomT : 1, transform: `scale(${(0.9 + 0.1 * zoomT).toFixed(4)})` }}><Funcoes t={t} /></AbsoluteFill>
      ) : null}
      {t >= TI - 0.02 && t < TP + 0.25 ? (
        <AbsoluteFill style={{ transform: `translateY(${(-up * 1080).toFixed(1)}px)` }}><Ias t={t} /></AbsoluteFill>
      ) : null}
      {t >= TI - 0.32 && t < TI + 0.32 ? (
        <div style={{ position: "absolute", left: 960 - 1300, top: -700, width: 2600, height: 2500, backgroundImage: ACC, transform: `rotate(18deg) translateX(${((band - 0.5) * 2 * 3600).toFixed(1)}px)` }} />
      ) : null}
      {t >= TP - 0.28 && t < TN + 0.24 ? (
        <AbsoluteFill style={{ transform: `translateY(${((1 - up) * 1080).toFixed(1)}px)` }}><Preco t={t} /></AbsoluteFill>
      ) : null}
      {t >= TN - 0.22 && t < TZ + 0.34 ? (
        <AbsoluteFill style={{ clipPath: `inset(0 ${((1 - split) * 50).toFixed(2)}% 0 ${((1 - split) * 50).toFixed(2)}%)` }}><Numero1 t={t} /></AbsoluteFill>
      ) : null}
      {t >= TZ - 0.22 ? (
        <AbsoluteFill style={{ clipPath: `circle(${(circ * 2300).toFixed(0)}px at 960px 540px)` }}><Fecho t={t} /></AbsoluteFill>
      ) : null}
    </AbsoluteFill>
    </Loc.Provider>
  );
};

